<?php $pageTitle='Candidate Discovery'; require 'config.php'; require 'includes/functions.php'; require_role('team_leader');$q=trim($_GET['q']??'');$min=(int)($_GET['min_trust']??0);$verified=isset($_GET['verified']);
$sql="SELECT DISTINCT u.id,u.name,u.email,u.college,u.branch,u.location,u.trust_score,u.bio FROM users u LEFT JOIN user_skills us ON us.user_id=u.id LEFT JOIN skills s ON s.id=us.skill_id WHERE u.role='student' AND u.trust_score>=?";$args=[$min];if($q!==''){$sql.=" AND (u.name LIKE ? OR u.college LIKE ? OR s.name LIKE ?)";$like="%$q%";$args[]=$like;$args[]=$like;$args[]=$like;}if($verified)$sql.=" AND EXISTS(SELECT 1 FROM user_skills ux WHERE ux.user_id=u.id AND ux.verified=1)";$sql.=" ORDER BY u.trust_score DESC";$stmt=$pdo->prepare($sql);$stmt->execute($args);$students=$stmt->fetchAll();include 'includes/header.php';?>
<div class="card"><h2>Candidate Discovery</h2><form method="get" class="grid"><div class="form-group"><label>Name, college or skill</label><input name="q" value="<?=e($q)?>"></div><div class="form-group"><label>Minimum Trust Score</label><input type="number" name="min_trust" min="0" max="100" value="<?=$min?>"></div><div class="form-group"><label>&nbsp;</label><label><input type="checkbox" name="verified" <?=$verified?'checked':''?>> Has verified skill</label><button class="btn">Search</button></div></form></div>
<h2 class="section-title">Candidates</h2><div class="grid"><?php foreach($students as $s):?><div class="card"><span class="badge"><?=e(trust_tier($s['trust_score']))?> • <?=e($s['trust_score'])?></span><h3><?=e($s['name'])?></h3><p class="muted"><?=e($s['college']?:'College not set')?> <?=e($s['branch']?'• '.$s['branch']:'')?></p><p><?=e($s['bio']?:'No bio yet.')?></p><p class="muted"><?=e($s['location'])?></p></div><?php endforeach;?></div>
<?php include 'includes/footer.php'; ?>
